684|int32_t nghttp2_submit_request(nghttp2_session *session,
685|                               const nghttp2_priority_spec *pri_spec,
686|                               const nghttp2_nv *nva, size_t nvlen,
687|                               const nghttp2_data_provider *data_prd,
688|                               void *stream_user_data) {
689|  uint8_t flags;
690|  int rv;
691|
692|  if (session->server) {
693|    return NGHTTP2_ERR_PROTO;
694|  }
695|
696|  if (pri_spec && !nghttp2_priority_spec_check_default(pri_spec) &&
697|      session->remote_settings.no_rfc7540_priorities != 1) {
698|    rv = detect_self_dependency(session, -1, pri_spec);
699|    if (rv != 0) {
